1	import { addDays, subDays, isWeekend, format, differenceInDays, isBefore, startOfDay } from "date-fns";
2	
3	/**
4	 * Parses a "YYYY-MM-DD" date string as local midnight.
5	 * Using new Date("YYYY-MM-DD") would parse as UTC midnight, which shifts
6	 * the date back one day in negative-offset (e.g. US) timezones.
7	 */
8	export function parseDateStr(dateStr: string): Date {
9	  const [year, month, day] = dateStr.split("-").map(Number);
10	  return new Date(year, month - 1, day);
11	}
12	
13	export function addBusinessDays(date: Date, amount: number): Date {
14	  let currentDate = date;
15	  let addedDays = 0;
16	  
17	  const step = amount > 0 ? 1 : -1;
18	  const targetDays = Math.abs(amount);
19	
20	  while (addedDays < targetDays) {
21	    currentDate = addDays(currentDate, step);
22	    if (!isWeekend(currentDate)) {
23	      addedDays++;
24	    }
25	  }
26	
27	  return currentDate;
28	}
29	
30	export function subBusinessDays(date: Date, amount: number): Date {
31	  return addBusinessDays(date, -amount);
32	}
33	
34	export function formatDate(dateStr?: string | null): string {
35	  if (!dateStr) return "-";
36	  const d = dateStr.includes("T") ? new Date(dateStr) : parseDateStr(dateStr);
37	  return format(d, "MMM d, yyyy");
38	}
39	
40	export function getUrgencyInfo(targetDateStr?: string | null) {
41	  if (!targetDateStr) return { color: "default", label: "NO DATE", daysRemaining: null, bgClass: "bg-gray-500", textClass: "text-gray-500" };
42	  
43	  const target = startOfDay(targetDateStr.includes("T") ? new Date(targetDateStr) : parseDateStr(targetDateStr));
44	  const today = startOfDay(new Date());
45	  
46	  const diff = differenceInDays(target, today);
47	  
48	  if (diff < 0)  return { color: "gray",   label: "PAST",        daysRemaining: diff, bgClass: "bg-gray-500",   textClass: "text-gray-500"   };
49	  if (diff <= 7)  return { color: "red",    label: "URGENT",      daysRemaining: diff, bgClass: "bg-red-500",    textClass: "text-red-500"    };
50	  if (diff <= 13) return { color: "amber",  label: "CLOSE",       daysRemaining: diff, bgClass: "bg-amber-500",  textClass: "text-amber-500"  };
51	  if (diff <= 30) return { color: "yellow", label: "SOON",        daysRemaining: diff, bgClass: "bg-yellow-500", textClass: "text-yellow-500" };
52	  if (diff <= 60) return { color: "green",  label: "IN PROGRESS", daysRemaining: diff, bgClass: "bg-green-500",  textClass: "text-green-500"  };
53	
54	  return { color: "indigo", label: "PLANNING", daysRemaining: diff, bgClass: "bg-indigo-500", textClass: "text-indigo-500" };
55	}
56	
57	export function getCategoryColor(category?: string | null) {
58	  switch (category) {
59	    case "Fire Marshal": return "bg-blue-500/10 text-blue-500 hover:bg-blue-500/20";
60	    case "ID Sign": return "bg-purple-500/10 text-purple-500 hover:bg-purple-500/20";
61	    case "Warehouse Manifest": return "bg-orange-500/10 text-orange-500 hover:bg-orange-500/20";
62	    case "Show Bucket": return "bg-yellow-500/10 text-yellow-500 hover:bg-yellow-500/20";
63	    case "Vehicle Spotting": return "bg-green-500/10 text-green-500 hover:bg-green-500/20";
64	    case "Electrical": return "bg-red-500/10 text-red-500 hover:bg-red-500/20";
65	    default: return "bg-gray-500/10 text-gray-500 hover:bg-gray-500/20";
66	  }
67	}
