78	function applySortToTasks(tasks: any[], mode: SortMode): any[] {
79	  const arr = [...tasks];
80	  switch (mode) {
81	    case "dueAsc":
82	      return arr.sort((a, b) => {
83	        if (!a.dueDate) return 1;
84	        if (!b.dueDate) return -1;
85	        return parseDateStr(a.dueDate).getTime() - parseDateStr(b.dueDate).getTime();
86	      });
87	    case "dueDesc":
88	      return arr.sort((a, b) => {
89	        if (!a.dueDate) return 1;
90	        if (!b.dueDate) return -1;
91	        return parseDateStr(b.dueDate).getTime() - parseDateStr(a.dueDate).getTime();
92	      });
93	    case "nameAz":
94	      return arr.sort((a, b) => a.name.localeCompare(b.name));
95	    case "category":
96	      return arr.sort((a, b) => (a.category ?? "").localeCompare(b.category ?? ""));
97	  }
98	}
