107	  const [filterCategories, setFilterCategories] = useState<string[]>([]);
108	  const [sortMode, setSortMode] = useState<SortMode>("dueAsc");
109	  const [groupMode, setGroupMode] = useState<"status" | "category">("status");
110	  const [filterOpen, setFilterOpen] = useState(false);
111	  const [completedOpen, setCompletedOpen] = useState(false);
112	  const [catSectionOpen, setCatSectionOpen] = useState<Record<string, boolean>>({});
113	
114	  const filteredTasks = useMemo(() => {
115	    if (!tasks) return [];
116	    if (filterCategories.length === 0) return tasks;
117	    return tasks.filter(t => filterCategories.includes(t.category ?? ""));
118	  }, [tasks, filterCategories]);
119	
120	  const groupedTasks = useMemo(() => {
121	    const today = startOfDay(new Date());
122	    const overdue: any[] = [];
123	    const upcoming: any[] = [];
124	    const completed: any[] = [];
125	
126	    for (const t of filteredTasks) {
127	      if (t.completed) { completed.push(t); continue; }
128	      if (t.dueDate) {
129	        const dueDate = startOfDay(parseDateStr(t.dueDate));
130	        if (differenceInDays(dueDate, today) < 0) overdue.push(t);
131	        else upcoming.push(t);
132	      } else {
133	        upcoming.push(t);
134	      }
135	    }
136	
137	    return {
138	      overdue: applySortToTasks(overdue, sortMode),
139	      upcoming: applySortToTasks(upcoming, sortMode),
140	      completed: completed.sort((a, b) => {
141	        if (!a.completedAt) return 1;
142	        if (!b.completedAt) return -1;
143	        return new Date(b.completedAt).getTime() - new Date(a.completedAt).getTime();
144	      }),
