670	function computePresetDate(preset: PresetTask, show: Show): { date: string; requires: unknown } {
671	  if (!preset.dueDateOffset || !preset.dueDateUnit || !preset.dueDateDirection || !preset.dueDateAnchor) {
672	    return { date: "", requires: true };
673	  }
674	  const anchor = (show as unknown as Record<string, unknown>)[preset.dueDateAnchor];
675	  if (!anchor) return { date: "", requires: null };
676	  const anchorDate = parseDateStr(anchor as string);
677	  const d =
678	    preset.dueDateDirection === "before"
679	      ? preset.dueDateUnit === "biz"
680	        ? subBusinessDays(anchorDate, preset.dueDateOffset)
681	        : subDays(anchorDate, preset.dueDateOffset)
682	      : preset.dueDateUnit === "biz"
683	        ? addBusinessDays(anchorDate, preset.dueDateOffset)
684	        : addDays(anchorDate, preset.dueDateOffset);
685	  return { date: format(d, "yyyy-MM-dd"), requires: anchor };
686	}
