689	  if (!preset.dueDateOffset) return "Manual entry — set due date after adding";
690	  const anchor = ANCHOR_DISPLAY[preset.dueDateAnchor!] ?? preset.dueDateAnchor ?? "";
691	  return `${preset.dueDateOffset} ${preset.dueDateUnit} days ${preset.dueDateDirection} ${anchor}`;
692	}
