194	  const [pomodoroOpen, setPomodoroOpen] = useState(false);
195	  const [presets, setPresets] = useState<[number, number, number]>([2, 5, 30]);
196	  const [selectedPreset, setSelectedPreset] = useState<0 | 1 | 2 | null>(null);
197	  const [timeLeft, setTimeLeft] = useState(0);
198	  const [isRunning, setIsRunning] = useState(false);
199	  const [timesUp, setTimesUp] = useState(false);
200	
201	  const items = useMemo(() => {
202	    if (!rawItems) return [];
203	    const dueToday = rawItems.filter(i => i.daysOverdue === 0);
204	    const overdue = rawItems
205	      .filter(i => i.daysOverdue > 0)
206	      .sort((a, b) => b.daysOverdue - a.daysOverdue);
207	    return [...dueToday, ...overdue];
208	  }, [rawItems]);
209	
210	  // Seed note drafts when items load
211	  useEffect(() => {
212	    if (!items.length) return;
213	    setNoteDrafts(prev => {
214	      const next = { ...prev };
215	      for (const item of items) {
216	        const k = itemKey(item.type, item.id);
217	        if (!(k in next)) next[k] = item.notes ?? "";
218	      }
219	      return next;
220	    });
221	  }, [items]);
222	
223	  // Countdown ticker
224	  useEffect(() => {
225	    if (!isRunning) return;
226	    intervalRef.current = setInterval(() => {
227	      setTimeLeft(t => {
228	        if (t <= 1) {
229	          clearInterval(intervalRef.current!);
230	          setIsRunning(false);
231	          setTimesUp(true);
232	          return 0;
233	        }
234	        return t - 1;
235	      });
236	    }, 1000);
237	    return () => clearInterval(intervalRef.current!);
238	  }, [isRunning]);
239	
240	  // Close pomodoro when navigating to a different card
241	  useEffect(() => {
242	    clearInterval(intervalRef.current!);
243	    setPomodoroOpen(false);
244	    setSelectedPreset(null);
245	    setTimeLeft(0);
246	    setIsRunning(false);
247	    setTimesUp(false);
248	  }, [index]);
249	
250	  const invalidate = () => {
251	    queryClient.invalidateQueries({ queryKey: getGetOverdueItemsQueryKey() });
252	    queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
253	  };
254	
255	  if (isLoading) return <Skeleton className="w-full h-40 rounded-lg" />;
256	  if (items.length === 0) return null;
257	
258	  const safeIndex = Math.min(index, items.length - 1);
259	  const item = items[safeIndex];
260	  const isToday = item.daysOverdue === 0;
261	  const total = items.length;
262	  const key = itemKey(item.type, item.id);
263	  const currentNote = noteDrafts[key] ?? item.notes ?? "";
264	  const isCompleting = completing[key] ?? false;
265	  const isNoteOpen = noteOpen[key] ?? false;
266	  const accentText = isToday ? "text-amber-400" : "text-red-400";
267	
268	  // ── Navigation ────────────────────────────────────────────────────────────
269	  const prev = () => setIndex(i => Math.max(0, i - 1));
270	  const next = () => setIndex(i => Math.min(total - 1, i + 1));
271	
272	  // ── Notes ─────────────────────────────────────────────────────────────────
273	  const saveNote = () => {
274	    const draft = currentNote;
275	    const original = item.notes ?? "";
276	    if (draft === original) return;
277	    if (item.type === "task") {
278	      updateTask.mutate(
279	        { showId: item.showId, taskId: item.id, data: { notes: draft || null } },
280	        { onSuccess: () => {
281	            setSavedFlash(p => ({ ...p, [key]: true }));
282	            setTimeout(() => setSavedFlash(p => ({ ...p, [key]: false })), 1500);
283	            invalidate();
284	          }
285	        }
286	      );
287	    } else {
288	      updateEblast.mutate(
289	        { showId: item.showId, eblastId: item.id, data: { notes: draft || null } },
290	        { onSuccess: () => {
291	            setSavedFlash(p => ({ ...p, [key]: true }));
292	            setTimeout(() => setSavedFlash(p => ({ ...p, [key]: false })), 1500);
293	            invalidate();
294	          }
295	        }
296	      );
297	    }
298	  };
299	
300	  const openNote = () => setNoteOpen(p => ({ ...p, [key]: true }));
301	  const closeNote = () => {
302	    saveNote();
303	    setNoteOpen(p => ({ ...p, [key]: false }));
304	  };
305	
306	  // ── Complete / Sent ───────────────────────────────────────────────────────
307	  const markComplete = () => {
308	    setCompleting(p => ({ ...p, [key]: true }));
309	    const now = new Date().toISOString();
310	    if (item.type === "task") {
311	      updateTask.mutate(
312	        { showId: item.showId, taskId: item.id, data: { completed: true, completedAt: now } },
313	        {
314	          onSuccess: () => {
315	            invalidate();
316	            setIndex(i => Math.max(0, Math.min(i, total - 2)));
317	            setCompleting(p => ({ ...p, [key]: false }));
318	          },
319	          onError: () => setCompleting(p => ({ ...p, [key]: false })),
320	        }
321	      );
322	    } else {
323	      updateEblast.mutate(
324	        { showId: item.showId, eblastId: item.id, data: { sent: true, sentAt: now } },
325	        {
326	          onSuccess: () => {
327	            invalidate();
328	            setIndex(i => Math.max(0, Math.min(i, total - 2)));
329	            setCompleting(p => ({ ...p, [key]: false }));
330	          },
331	          onError: () => setCompleting(p => ({ ...p, [key]: false })),
332	        }
333	      );
334	    }
335	  };
336	
337	  // ── Pomodoro helpers ──────────────────────────────────────────────────────
338	  const openPomodoro = () => setPomodoroOpen(true);
339	
340	  const closePomodoro = () => {
341	    clearInterval(intervalRef.current!);
342	    setPomodoroOpen(false);
343	    setSelectedPreset(null);
344	    setTimeLeft(0);
345	    setIsRunning(false);
346	    setTimesUp(false);
347	  };
348	
349	  const selectPreset = (i: 0 | 1 | 2) => {
350	    clearInterval(intervalRef.current!);
351	    setIsRunning(false);
352	    setTimesUp(false);
353	    setSelectedPreset(i);
354	    setTimeLeft(presets[i] * 60);
355	  };
356	
357	  const adjustPreset = (i: 0 | 1 | 2, delta: number) => {
358	    setPresets(p => {
359	      const next: [number, number, number] = [...p] as [number, number, number];
360	      next[i] = Math.max(1, next[i] + delta);
361	      if (selectedPreset === i) {
362	        clearInterval(intervalRef.current!);
363	        setIsRunning(false);
364	        setTimesUp(false);
365	        setTimeLeft(next[i] * 60);
366	      }
367	      return next;
368	    });
369	  };
370	
371	  const toggleTimer = () => {
372	    if (selectedPreset === null) return;
373	    if (timeLeft === 0) {
374	      setTimeLeft(presets[selectedPreset] * 60);
375	      setTimesUp(false);
376	    }
377	    setIsRunning(r => !r);
378	  };
379	
380	  const resetTimer = () => {
381	    clearInterval(intervalRef.current!);
382	    setIsRunning(false);
383	    setTimesUp(false);
384	    if (selectedPreset !== null) setTimeLeft(presets[selectedPreset] * 60);
385	  };
386	
387	  const showTab = item.type === "eblast" ? "eblasts" : "tasks";
388	  const completionLabel = item.type === "eblast" ? "Mark Sent" : "Mark Complete";
389	  const outerBorder = isToday ? "border-amber-500/35 bg-amber-500/[0.06]" : "border-red-500/35 bg-red-500/[0.06]";
390	  const iconRing = isToday ? "bg-amber-500/20" : "bg-red-500/20";
391	  const completeBtn = isToday
392	    ? "bg-amber-500 hover:bg-amber-400 text-black"
393	    : "bg-red-500 hover:bg-red-400 text-white";
394	  // kept for pomodoro view compat
395	  const headerBand = isToday
396	    ? "bg-amber-500/20 border-b border-amber-500/35"
397	    : "bg-red-500/20 border-b border-red-500/35";
398	
399	  // ── Pomodoro view ─────────────────────────────────────────────────────────
400	  if (pomodoroOpen) {
401	    return (
402	      <div className={`rounded-xl border ${outerBorder}`}>
403	        <div className="px-4 pt-4 pb-4 flex flex-col gap-2 min-h-[168px] justify-between">
404	
405	          {/* Row 1: Back (left) · chip (true center) · Focus Timer (right) */}
406	          <div className="relative flex items-center">
407	            <button
408	              onClick={closePomodoro}
409	              className="flex items-center gap-1 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors"
410	            >
411	              <ArrowLeft className="h-3 w-3" />
412	              Back
413	            </button>
414	            <span className={`absolute left-1/2 -translate-x-1/2 text-xs font-semibold px-2 py-0.5 rounded-md border ${chipClass(item.type, item.category)}`}>
415	              {item.type === "eblast" ? "E-Blast" : (item.category ?? "Task")}
416	            </span>
417	            <span className={`ml-auto text-xs font-bold uppercase tracking-widest ${accentText}`}>Focus Timer</span>
418	          </div>
419	
420	          {/* Row 2: task name — centered */}
421	          <p className="text-xl font-bold leading-snug text-center">{item.name}</p>
422	
423	          {/* Row 3: timer readout — centered */}
424	          <div className="flex flex-col items-center gap-0.5">
425	            <span className={`text-3xl font-black tabular-nums tracking-tight ${selectedPreset !== null ? accentText : "text-muted-foreground/30"}`}>
426	              {selectedPreset !== null ? formatTime(timeLeft) : "--:--"}
427	            </span>
428	            {timesUp && <span className={`text-xs font-semibold ${accentText}`}>Time's up!</span>}
429	          </div>
430	
431	          {/* Row 4: presets + Start/Reset — all centered on one line */}
432	          <div className="flex items-center justify-center gap-3 flex-wrap">
433	            {([0, 1, 2] as const).map(i => {
434	              const isSelected = selectedPreset === i;
435	              return (
436	                <div key={i} className="flex items-center gap-0.5">
437	                  <Button variant="ghost" size="icon" className="h-5 w-5" onClick={() => adjustPreset(i, -1)} disabled={presets[i] <= 1}>
438	                    <span className="text-xs leading-none">−</span>
439	                  </Button>
440	                  <button
441	                    onClick={() => selectPreset(i)}
442	                    className={`px-2 py-0.5 rounded text-xs font-medium border transition-colors ${
443	                      isSelected
444	                        ? "bg-primary/15 border-primary/40 text-primary"
445	                        : "border-border text-muted-foreground hover:text-foreground hover:border-muted-foreground"
446	                    }`}
447	                  >
448	                    {presets[i]}m
449	                  </button>
450	                  <Button variant="ghost" size="icon" className="h-5 w-5" onClick={() => adjustPreset(i, 1)}>
451	                    <span className="text-xs leading-none">+</span>
452	                  </Button>
453	                </div>
454	              );
455	            })}
456	
457	            <div className="w-px h-4 bg-border mx-1" />
458	
459	            <Button size="sm" className={`gap-1.5 ${completeBtn}`} onClick={toggleTimer} disabled={selectedPreset === null}>
460	              {isRunning
461	                ? <><Pause className="h-3.5 w-3.5" /> Pause</>
462	                : <><Play className="h-3.5 w-3.5" /> Start</>
463	              }
464	            </Button>
465	            <Button variant="outline" size="icon" className="h-8 w-8" onClick={resetTimer} disabled={selectedPreset === null} title="Reset">
466	              <RotateCcw className="h-3.5 w-3.5" />
467	            </Button>
468	          </div>
469	
470	        </div>
471	      </div>
472	    );
473	  }
474	
475	  // ── Default slider view ───────────────────────────────────────────────────
476	  const moveInDays = item.moveInDate
477	    ? differenceInDays(startOfDay(parseDateStr(item.moveInDate)), startOfDay(new Date()))
478	    : null;
479	  const moveInUrgency = item.moveInDate ? getUrgencyInfo(item.moveInDate) : null;
480	
481	  return (
482	    <div className={`rounded-xl border transition-opacity duration-300 ${isCompleting ? "opacity-40 pointer-events-none" : ""} ${outerBorder}`}>
483	      <div className="px-4 pt-5 pb-4 flex items-start gap-4 min-h-[168px]">
484	
485	        {/* Left: accent icon */}
486	        <div className={`rounded-full p-2.5 shrink-0 mt-0.5 ${iconRing}`}>
487	          <AlertTriangle className={`h-4 w-4 ${accentText}`} />
488	        </div>
489	
490	        {/* Content */}
491	        <div className="flex-1 min-w-0 flex flex-col gap-2">
492	
493	          {/* Row 1: urgency label + category chip */}
494	          <div className="flex items-center gap-2">
495	            <span className={`text-xs font-bold uppercase tracking-widest shrink-0 ${accentText}`}>
496	              {isToday ? "Due Today" : `${item.daysOverdue} ${item.daysOverdue === 1 ? "Day" : "Days"} Overdue`}
497	            </span>
498	            <span className={`text-xs font-semibold px-2 py-0.5 rounded-md border shrink-0 ${chipClass(item.type, item.category)}`}>
499	              {item.type === "eblast" ? "E-Blast" : (item.category ?? "Task")}
500	            </span>
501	          </div>
502	
503	          {/* Row 2: task name */}
504	          <p className="text-xl font-bold leading-snug">{item.name}</p>
505	
506	          {/* Row 3: show · due date */}
507	          <p className="text-sm text-muted-foreground">
508	            {item.showName}
509	            <span className="mx-1.5 opacity-40">•</span>
510	            Due {formatDate(item.dueDate)}
511	          </p>
512	
513	          {/* Row 4: note */}
514	          <div className="flex-1 min-w-0">
515	            {!isNoteOpen ? (
516	              <button
517	                onClick={openNote}
518	                className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors group"
519	              >
520	                <ChevronDown className="h-3 w-3 shrink-0 opacity-50 group-hover:opacity-80" />
521	                <span className="truncate">{currentNote || "Add a note…"}</span>
522	              </button>
523	            ) : (
524	              <div className="flex flex-col gap-1">
525	                <Textarea
526	                  key={key}
527	                  autoFocus
528	                  value={currentNote}
529	                  onChange={e => setNoteDrafts(p => ({ ...p, [key]: e.target.value }))}
530	                  onBlur={closeNote}
531	                  placeholder="Add a note…"
532	                  className="resize-none text-xs min-h-[48px]"
533	                  rows={2}
534	                />
535	                {savedFlash[key] && <span className="text-xs text-muted-foreground">Saved</span>}
536	              </div>
537	            )}
538	          </div>
539	
540	          {/* Pagination dots */}
541	          {total > 1 && total <= 10 && (
542	            <div className="flex items-center gap-1">
543	              {items.map((_, i) => (
544	                <button
545	                  key={i}
546	                  onClick={() => setIndex(i)}
547	                  className={`rounded-full transition-all ${
548	                    i === safeIndex
549	                      ? `h-1.5 w-4 ${isToday ? "bg-amber-400" : "bg-red-400"}`
550	                      : "h-1.5 w-1.5 bg-muted-foreground/30 hover:bg-muted-foreground/50"
551	                  }`}
552	                />
553	              ))}
554	            </div>
555	          )}
556	        </div>{/* /content */}
557	
558	        {/* Right panel: nav · days counter · action buttons — stacked vertically */}
559	        <div className="w-px self-stretch bg-border/50 shrink-0 mx-1" />
560	        <div className="flex flex-col items-center justify-between shrink-0 gap-2">
561	
562	          {/* Nav arrows */}
563	          <div className="flex items-center gap-0.5">
564	            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={prev} disabled={safeIndex === 0}>
565	              <ChevronLeft className="h-4 w-4" />
566	            </Button>
567	            <span className="text-xs text-muted-foreground tabular-nums font-medium px-1 select-none whitespace-nowrap">
568	              {safeIndex + 1} of {total}
569	            </span>
570	            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={next} disabled={safeIndex === total - 1}>
571	              <ChevronRight className="h-4 w-4" />
572	            </Button>
573	          </div>
574	
575	          {/* Days until move-in */}
576	          {moveInDays !== null && moveInUrgency ? (
577	            <div className="flex flex-col items-center gap-0 leading-none text-center">
578	              <span className={`text-3xl font-black tabular-nums tracking-tight ${moveInUrgency.textClass}`}>
579	                {Math.abs(moveInDays)}
580	              </span>
581	              <span className="text-[10px] uppercase font-semibold tracking-wider text-muted-foreground">
582	                {moveInDays < 0 ? "Days Ago" : "Days"}
583	              </span>
584	              <span className="text-[9px] uppercase tracking-wider text-muted-foreground/60 mt-0.5">
585	                Move-In
586	              </span>
587	            </div>
588	          ) : <div />}
589	
590	          {/* Action buttons */}
591	          <div className="flex items-center gap-1.5 flex-wrap justify-center">
592	            <Button variant="outline" size="icon" className="h-8 w-8" onClick={openPomodoro} title="Pomodoro timer">
593	              <Timer className="h-3.5 w-3.5" />
594	            </Button>
595	            <Button variant="outline" size="icon" className="h-8 w-8" onClick={() => setEditOpen(true)} title="Edit">
596	              <Edit2 className="h-3.5 w-3.5" />
597	            </Button>
598	            <Button
599	              size="sm"
600	              className={`gap-1.5 ${completeBtn}`}
601	              onClick={markComplete}
