603	            >
604	              <Check className="h-3.5 w-3.5" />
605	              {completionLabel}
606	            </Button>
607	            <Link href={`/shows/${item.showId}?tab=${showTab}`}>
608	              <Button variant="outline" size="sm">Open</Button>
609	            </Link>
610	          </div>
611	
612	        </div>{/* /right panel */}
613	      </div>
614	      <EditItemDialog
615	        item={item}
616	        open={editOpen}
617	        onOpenChange={setEditOpen}
618	        onSuccess={invalidate}
619	      />
620	    </div>
621	  );
622	}
